{"content": "#!/usr/bin/env python3
"""
enrichment-engine.py — Lead Enrichment Engine for Pipeline Data

Enriches leads from pipeline-*.json files with web research, signal detection,
and scoring. Uses DuckDuckGo search for company research.

Usage:
    python3 enrichment-engine.py                     # Enrich all stale/incomplete leads
    python3 enrichment-engine.py --report            # Status report only, no execution
    python3 enrichment-engine.py --pipeline saas     # Enrich only saas pipeline leads
"""

import json
import re
import sys
import time
from collections import Counter
from datetime import datetime, timezone, timedelta
from pathlib import Path

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

SCRIPT_DIR = Path(__file__).resolve().parent
DATA_DIR = SCRIPT_DIR  # Same directory as this script

STALE_DAYS = 7
SIGNALS_REPORT_FILE = DATA_DIR / "signals-report.json"
SEARCH_DELAY_SECONDS = 1.5  # short delay between searches

# ---------------------------------------------------------------------------
# Signal detection patterns
# ---------------------------------------------------------------------------

SIGNAL_PATTERNS = {
    "key_player_changed": {
        "keywords": [
            r"\b(?:new\s+)?(?:CEO|CTO|CFO|COO|VP|Chief\s+(?:Executive|Technology|Financial|Operating|Marketing|Product))\s+(?:appointed|hired|joins?|leaves?|departs?|resigns?|steps?\s+down|named|promoted)\b",
            r"\b(?:appointed|hired|named|promoted)\s+(?:as\s+)?(?:new\s+)?(?:CEO|CTO|CFO|COO|VP|Chief\s+(?:Executive|Technology|Financial|Operating|Marketing|Product))\b",
            r"\b(?:leadership|executive|C-suite|management)\s+(?:change|shake.?up|reorg|restructure|transition)\b",
        ],
        "weight": 3,
    },
    "cyber_breach": {
        "keywords": [
            r"\b(?:data\s+)?breach\b",
            r"\b(?:cyber|security|ransomware|hack|malware|phishing)\s+(?:attack|incident|breach|violation|intrusion)\b",
            r"\b(?:data\s+)?leak\b",
            r"\b(?:[Ii]nformation\s+)?[Ss]ecurity\s+incident\b",
            r"\b(?:PII|personally\s+identifiable\s+information)\s+(?:exposed|compromised|stolen)\b",
        ],
        "weight": 4,
    },
    "funding_round": {
        "keywords": [
            r"\b(?:raised|secured|closed|announced)\s+(?:a\s+)?\$[\d,.kmb]+\s+(?:in\s+)?(?:funding|financing|capital|investment|round|Series\s+[A-Z])\b",
            r"\b(?:funding|investment)\s+(?:round|raise)\s+of\s+\$[\d,.kmb]+\b",
            r"\b(?:Series\s+[A-Z]|Seed|Pre.?Seed|IPO|venture\s+capital)\s+(?:round|funding|raise)\b",
            r"\b(?:investor|VC|venture\s+firm)\s+(?:backs|invests|leads|participates)\b",
        ],
        "weight": 3,
    },
    "growth_downsizing": {
        "keywords": [
            r"\b(?:hiring\s+(?:spree|boom|surge|push|initiative|hundreds|thousands))\b",
            r"\b(?:expanding|expansion|growth|new\s+offices?)\s+(?:team|workforce|hiring|staff)\b",
            r"\b(?:plans?\s+to\s+)?(?:hire|add|recruit)\s+[\d,]+\s+(?:new\s+)?(?:employees?|staff|workers|people|roles?)\b",
            r"\b(?:lay(?:ing)?\s*off|laid\s+off|furlough|reduction\s+in\s+force|RIF|downsiz(?:ing|e))\b",
            r"\b(?:cut|slash|eliminate|reduce)\s+(?:jobs?|positions?|workforce|staff|headcount)\b",
            r"\b(?:restructur(?:ing|e)|reorg|right.?siz(?:ing|e))\s+(?:plan|announce|affect|cut)\b",
        ],
        "weight": 3,
    },
    "product_launch": {
        "keywords": [
            r"\b(?:launch(?:es|ed|ing)?|unveil(?:s|ed|ing)?|introduc(?:es|ed|ing)?|releas(?:es|ed|ing)?|debut(?:s|ed|ing)?)\s+(?:new\s+)?(?:product|platform|service|solution|app|feature|tool|version)\b",
            r"\b(?:new\s+)?(?:product|platform|service|solution|app|feature|tool|version)\s+(?:launch|unveil|release|debut|announce)\b",
            r"\b(?:beta|GA|general\s+availability|private\s+preview|public\s+launch)\s+(?:of|for|launch)\b",
        ],
        "weight": 2,
    },
}


# ---------------------------------------------------------------------------
# Scoring helpers
# ---------------------------------------------------------------------------

def score_verification(lead: dict) -> int:
    """
    verification_score (0-10): How much verifiable data we have on the company.
    """
    score = 0
    enriched = lead.get("enriched", {}) or {}
    notes = lead.get("notes", "") or ""

    has_website = bool(enriched.get("website") or "website" in notes.lower())
    has_location = bool(
        enriched.get("location")
        or re.search(r"\b(?:city|state|country|address|location)", notes, re.I)
    )
    has_leadership = bool(
        enriched.get("leadership")
        or re.search(r"\b(?:CEO|CTO|CFO|founder|president)", notes, re.I)
    )
    has_news = bool(
        enriched.get("recent_news")
        or re.search(r"\b(?:news|announce|report)", notes, re.I)
    )
    has_signals = bool(enriched.get("signals") and len(enriched.get("signals", [])) > 0)

    if has_website:
        score += 3
    if has_location:
        score += 2
    if has_leadership:
        score += 2
    if has_news:
        score += 2
    if has_signals:
        score += 1
    return min(score, 10)


def score_contact_availability(lead: dict) -> int:
    """contact_availability (0-10): How easy is this lead to reach."""
    score = 0
    contact = lead.get("contact", {}) or {}
    enriched = lead.get("enriched", {}) or {}

    email = contact.get("email") or enriched.get("email") or ""
    phone = contact.get("phone") or enriched.get("phone") or ""

    if email:
        score += 5
    if phone:
        score += 3

    linkedin = enriched.get("linkedin") or contact.get("linkedin") or ""
    if linkedin:
        score += 2

    return min(score, 10)


def score_fit(lead: dict) -> int:
    """
    fit_score (0-10): How well this lead fits the target profile
    based on signals and data.
    """
    score = 5  # Start at neutral
    enriched = lead.get("enriched", {}) or {}
    signals = enriched.get("signals", []) or []

    for signal in signals:
        signal_type = signal.get("signal_type", "")
        if signal_type in ("funding_round", "product_launch"):
            score += 2
        elif signal_type == "growth_downsizing":
            text = signal.get("evidence", "").lower()
            if any(w in text for w in ("hire", "expand", "grow", "new office")):
                score += 2
            else:
                score -= 1
        elif signal_type == "key_player_changed":
            text = signal.get("evidence", "").lower()
            if any(w in text for w in ("join", "appoint", "promote", "named")):
                score += 1
            else:
                score -= 1
        elif signal_type == "cyber_breach":
            score -= 2

    if enriched.get("website"):
        score += 1
    if enriched.get("leadership"):
        score += 1
    if enriched.get("location"):
        score += 1

    return max(0, min(score, 10))


def compute_scores(lead: dict) -> dict:
    """Compute all three scores and return as dict."""
    verification = score_verification(lead)
    contact_avail = score_contact_availability(lead)
    fit = score_fit(lead)
    return {
        "verification_score": verification,
        "contact_availability": contact_avail,
        "fit_score": fit,
        "total_score": verification + contact_avail + fit,
    }


# ---------------------------------------------------------------------------
# Web research
# ---------------------------------------------------------------------------

def search_company(company_name: str) -> dict:
    """Search for company info via DuckDuckGo. Returns extracted data."""
    result = {
        "website": "",
        "location": "",
        "leadership": "",
        "recent_news": [],
        "search_summary": "",
    }

    if not company_name:
        return result

    try:
        from duckduckgo_search import DDGS
    except ImportError:
        print(
            "[WARN] duckduckgo_search not installed. "
            "Install with: pip install duckduckgo_search"
        )
        return result

    all_texts = []
    ddgs = DDGS()

    try:
        general_query = f"{company_name} company overview"
        gen_results = list(ddgs.text(general_query, max_results=5))
        all_texts.extend(r.get("body", "") for r in gen_results if r.get("body"))
        time.sleep(SEARCH_DELAY_SECONDS)
    except Exception as e:
        print(f"  [WARN] General search failed: {e}")

    try:
        news_query = f"{company_name} news"
        news_results = list(ddgs.text(news_query, max_results=5))
        news_bodies = [r.get("body", "") for r in news_results if r.get("body")]
        all_texts.extend(news_bodies)
        result["recent_news"] = news_bodies[:3]
        time.sleep(SEARCH_DELAY_SECONDS)
    except Exception as e:
        print(f"  [WARN] News search failed: {e}")

    try:
        lead_query = f"{company_name} CEO leadership team"
        lead_results = list(ddgs.text(lead_query, max_results=3))
        all_texts.extend(r.get("body", "") for r in lead_results if r.get("body"))
        time.sleep(SEARCH_DELAY_SECONDS)
    except Exception as e:
        print(f"  [WARN] Leadership search failed: {e}")

    combined = " ".join(all_texts)

    # ---- Extract website ----
    url_pattern = re.compile(
        r"https?://(?:www\.)?([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)+)(?:[/\s\"'<>,;)\]|$)"
    )
    urls = url_pattern.findall(combined)
    skip_domains = {
        "google.com", "bing.com", "duckduckgo.com", "yahoo.com",
        "youtube.com", "linkedin.com", "facebook.com", "twitter.com",
        "x.com", "crunchbase.com", "bloomberg.com",
    }
    real_urls = [u for u in urls if u not in skip_domains]
    if real_urls:
        domain_counts = Counter(real_urls)
        most_common = domain_counts.most_common(1)[0][0]
        if most_common.count(".") >= 1:
            result["website"] = f"https://{most_common}"

    # ---- Extract location ----
    location_patterns = [
        r"\b(?:based in|headquartered in|located in|offices? in)\s+"
        r"([A-Z][a-zA-Z]+(?:,\s*[A-Z]{2})?(?:,\s*[A-Za-z]+)?)",
        r"\b([A-Z][a-zA-Z]+(?:,\s*[A-Z]{2}))\s+(?:area|metro|region)",
    ]
    for pat in location_patterns:
        m = re.search(pat, combined)
        if m:
            result["location"] = m.group(1).strip()
            break

    # ---- Extract leadership ----
    leadership_patterns = [
        r"(?:CEO|CTO|CFO|COO|President|Founder|Chief\s+\w+)\s*[:\-–]\s*"
        r"([A-Z][a-zA-Z]+\s+[A-Z][a-zA-Z]+)",
        r"([A-Z][a-zA-Z]+\s+[A-Z][a-zA-Z]+)\s*,\s*"
        r"(?:CEO|CTO|CFO|COO|President|Founder|Chief\s+\w+)",
    ]
    leaders = []
    for pat in leadership_patterns:
        for m in re.finditer(pat, combined):
            leaders.append(m.group(0))
    if leaders:
        result["leadership"] = "; ".join(leaders[:3])

    result["search_summary"] = combined[:500]

    try:
        ddgs.close()
    except Exception:
        pass

    return result


# ---------------------------------------------------------------------------
# Signal detection
# ---------------------------------------------------------------------------

def detect_signals(search_text: str) -> list:
    """Scan search text for signal patterns. Returns list of signal dicts."""
    signals = []
    if not search_text:
        return signals

    text_lower = search_text.lower()

    for signal_type, config in SIGNAL_PATTERNS.items():
        for pattern in config["keywords"]:
            matches = re.findall(pattern, text_lower, re.IGNORECASE)
            if matches:
                match_text = matches[0]
                evidence = match_text if isinstance(match_text, str) else match_text[0]
                is_dup = any(
                    existing["signal_type"] == signal_type for existing in signals
                )
                if not is_dup:
                    signals.append({
                        "signal_type": signal_type,
                        "evidence": evidence[:200],
                        "detected_at": datetime.now(timezone.utc).isoformat(),
                        "weight": config["weight"],
                    })
                break

    return signals


# ---------------------------------------------------------------------------
# Pipeline file handling
# ---------------------------------------------------------------------------

def find_pipeline_files(pipeline_filter: str = None) -> list:
    """Find all pipeline-*.json files in the data directory."""
    if pipeline_filter:
        pattern = f"pipeline-{pipeline_filter}.json"
    else:
        pattern = "pipeline-*.json"
    return sorted(DATA_DIR.glob(pattern))


def needs_enrichment(lead: dict) -> bool:
    """Determine if a lead needs enrichment (missing contact or stale >7 days)."""
    contact = lead.get("contact", {}) or {}
    has_email = bool(contact.get("email"))
    has_phone = bool(contact.get("phone"))

    if not has_email and not has_phone:
        return True

    enriched_at = lead.get("enriched_at")
    if enriched_at:
        try:
            enriched_dt = datetime.fromisoformat(enriched_at)
            if datetime.now(timezone.utc) - enriched_dt < timedelta(days=STALE_DAYS):
                return False
        except (ValueError, TypeError):
            pass

    return True


def enrich_lead(lead: dict, company_name: str = None) -> dict:
    """Perform full enrichment on a single lead."""
    if company_name is None:
        company_name = lead.get("company", lead.get("name", ""))

    print(f"  Enriching: {company_name}...")

    research = search_company(company_name)

    search_text = research.get("search_summary", "")
    news_text = " ".join(research.get("recent_news", []))
    combined_text = search_text + " " + news_text
    signals = detect_signals(combined_text)

    enriched = lead.get("enriched", {}) or {}
    enriched["website"] = research.get("website") or enriched.get("website", "")
    enriched["location"] = research.get("location") or enriched.get("location", "")
    enriched["leadership"] = research.get("leadership") or enriched.get("leadership", "")
    enriched["recent_news"] = research.get("recent_news") or enriched.get("recent_news", [])
    enriched["signals"] = signals
    enriched["last_researched"] = datetime.now(timezone.utc).isoformat()

    lead["enriched"] = enriched
    lead["enriched_at"] = datetime.now(timezone.utc).isoformat()

    scores = compute_scores(lead)
    lead["scores"] = scores

    now_str = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    notes = lead.get("notes", "") or ""
    notes += (
        f"\n[Enrichment {now_str}]"
        f"\n  Website: {research.get('website', 'N/A')}"
        f"\n  Location: {research.get('location', 'N/A')}"
        f"\n  Leadership: {research.get('leadership', 'N/A')}"
        f"\n  Signals detected: {len(signals)}"
        f"\n  Scores: V={scores['verification_score']} "
        f"C={scores['contact_availability']} "
        f"F={scores['fit_score']} "
        f"Total={scores['total_score']}/30"
    )
    lead["notes"] = notes.strip()

    print(f"    -> Signals: {[s['signal_type'] for s in signals]}")
    print(f"    -> Scores: V={scores['verification_score']} "
          f"C={scores['contact_availability']} "
          f"F={scores['fit_score']} "
          f"Total={scores['total_score']}/30")
    return lead


# ---------------------------------------------------------------------------
# Signals report
# ---------------------------------------------------------------------------

def update_signals_report(all_leads: list):
    """Aggregate all signals across all enriched leads and save to JSON."""
    report = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "total_leads_scored": 0,
        "total_signals_detected": 0,
        "signal_breakdown": {},
        "top_signals": [],
        "leads_with_signals": [],
    }

    for lead in all_leads:
        enriched = lead.get("enriched", {}) or {}
        signals = enriched.get("signals", []) or []
        scores = lead.get("scores", {})

        if not signals and not scores:
            continue

        report["total_leads_scored"] += 1
        lead_name = lead.get("company", lead.get("name", "Unknown"))

        if signals:
            report["total_signals_detected"] += len(signals)
            report["leads_with_signals"].append({
                "company": lead_name,
                "signals": signals,
                "scores": scores,
            })

            for signal in signals:
                st = signal["signal_type"]
                if st not in report["signal_breakdown"]:
                    report["signal_breakdown"][st] = {
                        "count": 0,
                        "weight": signal["weight"],
                    }
                report["signal_breakdown"][st]["count"] += 1

    breakdown = report["signal_breakdown"]
    report["top_signals"] = sorted(
        [
            {
                "type": k,
                "count": v["count"],
                "weight": v["weight"],
                "score": v["count"] * v["weight"],
            }
            for k, v in breakdown.items()
        ],
        key=lambda x: x["score"],
        reverse=True,
    )

    try:
        with open(SIGNALS_REPORT_FILE, "w") as f:
            json.dump(report, f, indent=2)
        print(f"\n  Signals report saved to: {SIGNALS_REPORT_FILE}")
    except IOError as e:
        print(f"  [ERROR] Could not write signals report: {e}")


# ---------------------------------------------------------------------------
# Report mode
# ---------------------------------------------------------------------------

def print_report():
    """Print status report for all pipeline files without executing enrichment."""
    files = find_pipeline_files()
    if not files:
        print("No pipeline-*.json files found.")
        return

    total_leads = 0
    stale_leads = 0
    complete_leads = 0

    for fpath in files:
        try:
            with open(fpath) as f:
                data = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            print(f"  [ERROR] Could not read {fpath.name}: {e}")
            continue

        leads = _extract_leads(data)
        pipeline_stale = 0
        pipeline_complete = 0

        for lead in leads:
            total_leads += 1
            if needs_enrichment(lead):
                pipeline_stale += 1
            else:
                pipeline_complete += 1
                complete_leads += 1

        stale_leads += pipeline_stale
        print(
            f"  {fpath.name}: {len(leads)} leads "
            f"({pipeline_stale} stale, {pipeline_complete} current)"
        )

    print(
        f"\n  Total: {total_leads} leads across {len(files)} pipeline(s)"
    )
    print(f"  Need enrichment: {stale_leads}")
    print(f"  Up-to-date: {complete_leads}")


def _extract_leads(data):
    """Extract a list of leads from various JSON structures."""
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("leads", "entries", "leads"):
            if key in data:
                val = data[key]
                if isinstance(val, list):
                    return val
                if isinstance(val, dict):
                    return [val]
        return [data]
    return []


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    args = sys.argv[1:]

    report_only = "--report" in args
    pipeline_filter = None
    if "--pipeline" in args:
        idx = args.index("--pipeline")
        if idx + 1 < len(args) and not args[idx + 1].startswith("--"):
            pipeline_filter = args[idx + 1]

    if report_only:
        print("\n=== Pipeline Enrichment Status Report ===\n")
        print_report()
        return

    files = find_pipeline_files(pipeline_filter)
    if not files:
        pattern = (
            f"pipeline-{pipeline_filter}.json"
            if pipeline_filter
            else "pipeline-*.json"
        )
        print(f"No files matching '{pattern}' found in {DATA_DIR}")
        print("Create pipeline JSON files first, e.g.:")
        print(
            '  echo \'[{"company": "Acme Corp", "contact": {}}]\' '
            "> pipeline-saas.json"
        )
        sys.exit(1)

    print("\n=== Enrichment Engine ===")
    print(f"Data directory: {DATA_DIR}")
    print(f"Pipeline filter: {pipeline_filter or 'all'}")
    print(f"Files found: {[f.name for f in files]}")
    print()

    all_processed_leads = []

    for fpath in files:
        print(f"Processing: {fpath.name}")
        try:
            with open(fpath) as f:
                data = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            print(f"  [ERROR] Could not read {fpath.name}: {e}")
            continue

        is_list = isinstance(data, list)
        is_dict = isinstance(data, dict)

        if is_list:
            leads = data
        elif is_dict:
            leads = _extract_leads(data)
        else:
            print(f"  [ERROR] Unsupported data format in {fpath.name}")
            continue

        pipeline_updated = False

        for i, lead in enumerate(leads):
            if needs_enrichment(lead):
                company = lead.get("company", lead.get("name", f"Lead {i}"))
                leads[i] = enrich_lead(lead, company)
                pipeline_updated = True
            else:
                comp = lead.get("company", lead.get("name", f"Lead {i}"))
                print(f"  Skipping (current): {comp}")

        if pipeline_updated:
            if is_list:
                out_data = leads
            elif is_dict:
                if "leads" in data:
                    data["leads"] = leads
                elif "entries" in data:
                    data["entries"] = leads
                else:
                    data = leads
                out_data = data
            else:
                out_data = leads

            try:
                with open(fpath, "w") as f:
                    json.dump(out_data, f, indent=2)
                print(f"  -> Updated {fpath.name}")
            except IOError as e:
                print(f"  [ERROR] Could not write {fpath.name}: {e}")

        all_processed_leads.extend(
            leads if isinstance(leads, list) else [leads]
        )

    if all_processed_leads:
        update_signals_report(all_processed_leads)

    print("\nDone.")


if __name__ == "__main__":
    main()
